CREATE VIEW v_set_translations AS SELECT set_translations.id AS id, set_translations.language AS language, set_translations.setCode AS setCode, set_translations.translation AS translation, setCode.id AS setCode_id, setCode.baseSetSize AS setCode_baseSetSize, setCode.block AS setCode_block, setCode.booster AS setCode_booster, setCode.isFoilOnly AS setCode_isFoilOnly, setCode.isForeignOnly AS setCode_isForeignOnly, setCode.isNonFoilOnly AS setCode_isNonFoilOnly, setCode.isOnlineOnly AS setCode_isOnlineOnly, setCode.isPartialPreview AS setCode_isPartialPreview, setCode.keyruneCode AS setCode_keyruneCode, setCode.mcmId AS setCode_mcmId, setCode.mcmIdExtras AS setCode_mcmIdExtras, setCode.mcmName AS setCode_mcmName, setCode.mtgoCode AS setCode_mtgoCode, setCode.name AS setCode_name, setCode.parentCode AS setCode_parentCode, setCode.releaseDate AS setCode_releaseDate, setCode.tcgplayerGroupId AS setCode_tcgplayerGroupId, setCode.totalSetSize AS setCode_totalSetSize, setCode.type AS setCode_type FROM set_translations LEFT JOIN sets AS setCode ON set_translations.setCode = setCode.code;
